-- Weekly Arena 2027-W03: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2027-W03', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2027-01-18T00:00:00.000Z', '2027-01-25T00:00:00.000Z', 60, 'published', $WK49ab68e8275a$[{"id":"wk-2027-w03-01-912f","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $24$ and $4$ and each non-parallel side has length $26$. Find its area.","type":"text","correctAnswer":"336","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $10$ and hypotenuse $26$.","solution":"The height is $\\sqrt{26^2-10^2}=24$, so the area is $\\tfrac12(24+4)(24)=336$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w03-02-82e0","title":"Sum of Divisors","topic":"Number Theory","level":"Foundation","question":"Find the sum of all positive divisors of $11250$.","type":"text","correctAnswer":"30459","hint":"Factor $N$ into primes; the divisor sum is multiplicative.","solution":"$11250=3^{2}\\cdot 2^{1}\\cdot 5^{4}$, so the divisor sum is $30459$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w03-03-99fa","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $40$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=8$. Find $PA + PB + PT$.","type":"text","correctAnswer":"248","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=40^2/8=200$, so the sum is $8+200+40=248$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2027-w03-04-0f0e","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 3 \\pmod{5}$, $n\\equiv 5 \\pmod{7}$, $n\\equiv 4 \\pmod{9}$.","type":"text","correctAnswer":"103","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $103$ modulo $315$, and $103$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w03-05-3c13","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $297$ that are divisible by $6$ or by $11$ (or both).","type":"text","correctAnswer":"10848","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $6$, $11$ and $66$ gives $10848$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2027-w03-06-bd87","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{50} \\left\\lfloor \\frac{6k}{11} \\right\\rfloor$.","type":"text","correctAnswer":"673","hint":"Write $6k=11q+r$ and track how the remainder cycles with period $11$.","solution":"Evaluating each floor term and adding gives $673$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w03-07-9ef0","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 3-tuples $(x_1,\\dots,x_3)$ of non-negative integers satisfy $x_1+\\cdots+x_3=14$ with every $x_i\\le 6$?","type":"text","correctAnswer":"15","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $15$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2027-w03-08-edcc","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 8t + 1 = 0$. Find the remainder when $r^{5} + s^{5}$ is divided by $1000$.","type":"text","correctAnswer":"248","hint":"Let $S_k=r^k+s^k$. Then $S_k=8S_{k-1}-1S_{k-2}$, with $S_0=2$, $S_1=8$.","solution":"Using $S_k=8S_{k-1}-1S_{k-2}$ from $S_0=2$, $S_1=8$ gives $S_{5}=30248$, whose remainder modulo $1000$ is $248$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w03-09-bac0","title":"Rearranging a Word","topic":"Combinatorics","level":"Advanced","question":"In how many distinct ways can the letters of $\\text{DDBCCCN}$ be rearranged so that no two identical letters are adjacent?","type":"text","correctAnswer":"96","hint":"Count all arrangements, then use inclusion-exclusion by gluing identical letters together.","solution":"Inclusion-exclusion (confirmed by exhaustive enumeration) gives $96$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":4,"points":73,"difficulty":0.52},{"id":"wk-2027-w03-10-3711","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(7,3)$ and $(7,8)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"15","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $35$ and the boundary has $B=7$ lattice points, so $I=(35-7+2)/2=15$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK49ab68e8275a$::jsonb
